mapper.select:
SELECT t2.`name` AS product_name, t3.short_name AS customer_name, t1.id, t1.customer_id, t1.product_id, t1.authorized_price, t1.creator, t1.create_time, t1.updater, t1.update_time FROM zc_customer_product_price t1 LEFT JOIN zc_product t2 ON t1.product_id = t2.id AND t2.deleted = 0 LEFT JOIN zc_customer t3 ON t1.customer_id = t3.id AND t3.deleted = 0 WHERE t1.deleted = 0
AND t1.customer_id = #{reqVO.customerId}
AND t1.product_id = #{reqVO.productId}
ORDER BY t1.id DESC
